py -c "
import pymupdf, glob, os, re, json, math, collections
# extract CV texts
cv={}
for f in sorted(glob.glob(r'DATA\CV\*.pdf')):
    d=pymupdf.open(f); cv[os.path.basename(f)[:-4]]='\n'.join(p.get_text() for p in d)
# extract hired CV part
def toks(s):
    return re.findall(r'[a-z0-9]+', s.lower())
def vec(s):
    c=collections.Counter(toks(s)); n=math.sqrt(sum(v*v for v in c.values())) or 1
    return {k:v/n for k,v in c.items()}
cvvec={k:vec(v) for k,v in cv.items()}
res={}
for f in sorted(glob.glob(r'DATA\JD+HiredCV\*.pdf')):
    d=pymupdf.open(f); txt='\n'.join(p.get_text() for p in d)
    idx=txt.find('CV OF THE HIRED CANDIDATE')
    hired=txt[idx:] if idx>=0 else txt
    hv=vec(hired)
    sims=[]
    for k,v in cvvec.items():
        s=sum(hv.get(t,0)*v.get(t,0) for t in hv)
        sims.append((round(s,4),k))
    sims.sort(reverse=True)
    res[os.path.basename(f)]=sims[:5]
print(json.dumps(res,indent=1))
"
